import{_ as t,o as e,c as s,a3 as r}from"./chunks/framework.CVt6dz2a.js";const u=JSON.parse('{"title":"EP.26 每个像素都在偷偷加班","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.26-overdraw-heatmap.md","filePath":"comics/EP.26-overdraw-heatmap.md","lastUpdated":1793881879000}'),i={name:"comics/EP.26-overdraw-heatmap.md"};function d(o,a,l,n,h,p){return e(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="ep-26-每个像素都在偷偷加班" tabindex="-1">EP.26 每个像素都在偷偷加班 <a class="header-anchor" href="#ep-26-每个像素都在偷偷加班" aria-label="Permalink to &quot;EP.26 每个像素都在偷偷加班&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/26-gpu-profiling/advanced">26.2 进阶应用：Overdraw、带宽与显存账本</a> 延伸阅读：<a href="./../guide/26-gpu-profiling/basics">26.1 基础入门：CPU 与 GPU 帧时间拆解</a> · <a href="./../guide/26-gpu-profiling/practice">26.3 实战案例：性能治理工作台</a> 动手演示：<a href="./../public/demos/gpu-profiling/frame-budget-lab.html">frame-budget-lab 帧时间拆解台</a> · <a href="./../public/demos/gpu-profiling/overdraw-heatmap.html">overdraw-heatmap 过度绘制热力图</a> · <a href="./../public/demos/gpu-profiling/drawcall-budget-lab.html">drawcall-budget-lab draw call 对照台</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱给场景加了一层雾效，画面立刻像蒙了层灰、帧率从 55 掉到 24；标签君补刀：粒子一多连鼠标都飘。</td></tr><tr><td>② 揭秘</td><td>码叔在白板上画了三个叠在一起的半透明方块：同一个像素被着色三次，这就是 overdraw。</td></tr><tr><td>③ 实证</td><td>打开热力图，红色区域集中在雾效与粒子堆上；读数显示平均 4.2 倍、片元数涨了四倍。</td></tr><tr><td>④ 结案</td><td>三刀砍过度绘制：减少大面积半透明、合并后处理 Pass、单通道数据别用 RGBA；先量再砍。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-只加了一层雾-为什么像换了个场景" tabindex="-1">① &quot;只加了一层雾&quot;，为什么像换了个场景 <a class="header-anchor" href="#_1-只加了一层雾-为什么像换了个场景" aria-label="Permalink to &quot;① &quot;只加了一层雾&quot;，为什么像换了个场景&quot;">​</a></h3><p>雾效、光晕、粒子、玻璃，这些&quot;看起来轻&quot;的东西，在 GPU 眼里一点都不轻。它们通常在<strong>同一个屏幕像素上叠了好几层</strong>，而每一层都要跑一次片元着色器、读一次纹理、做一次混合。你看到的是一层薄雾，GPU 干的是三到五倍的活。</p><p>更隐蔽的是：这类代价<strong>不体现在 draw calls 上</strong>。雾效可能只是一个全屏 pass，粒子可能只有一个 InstancedMesh——<code>renderer.info</code> 的数字很漂亮，帧时间却已经爆了。这正是 <a href="./../guide/26-gpu-profiling/basics">26.1</a> 强调&quot;CPU 与 GPU 两条时间线&quot;的原因。</p><h3 id="_2-overdraw-同一个像素被画了几次" tabindex="-1">② overdraw：同一个像素被画了几次 <a class="header-anchor" href="#_2-overdraw-同一个像素被画了几次" aria-label="Permalink to &quot;② overdraw：同一个像素被画了几次&quot;">​</a></h3><p>overdraw 的来源只有三类：</p><table tabindex="0"><thead><tr><th>来源</th><th>例子</th><th>单像素次数</th></tr></thead><tbody><tr><td>前后遮挡</td><td>墙后还有一排楼</td><td>2~5</td></tr><tr><td>半透明叠加</td><td>雾、玻璃、粒子、光晕</td><td>5~50</td></tr><tr><td>全屏 Pass</td><td>后处理链</td><td>每 Pass +1</td></tr></tbody></table><p>它的总代价 ≈ <strong>像素数 × 每像素指令数 × overdraw 倍数</strong>。像素数又等于宽 × 高 × DPR²，所以&quot;分辨率翻倍、overdraw 不变&quot;时，片元总量仍然变成 4 倍。</p><p>可视化方法很直接：把所有物体换成&quot;输出常量 1、开启加法混合、关闭深度测试&quot;的材质，画进一张浮点缓冲；红通道的值就是该像素被着色的次数，再按 黑→蓝→青→黄→红 上色，就是热力图。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setRenderTarget</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(countRT)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 半精度浮点缓冲</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setClearColor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0x000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">renderer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(countScene, camera) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 每画一层，红通道 +1</span></span></code></pre></div><h3 id="_3-半透明的两笔账-排序与混合" tabindex="-1">③ 半透明的两笔账：排序与混合 <a class="header-anchor" href="#_3-半透明的两笔账-排序与混合" aria-label="Permalink to &quot;③ 半透明的两笔账：排序与混合&quot;">​</a></h3><p>透明物体每帧要按距离排序（CPU 的 <code>O(n log n)</code>），还要从远到近绘制；GPU 侧因为要混合，通常<strong>不能 early-z</strong>，被遮挡的片元也必须真的着色。两层账叠加，让&quot;大面积半透明&quot;成为最不划算的画法之一。</p><p>替代方案：能用 <code>alphaTest</code> 就别用 <code>transparent</code>（可被深度测试裁掉）；能用加法混合就别用普通混合（顺序无关、可关排序）；粒子尽量合图集、降层数。</p><h3 id="_4-后处理-每个-pass-都是一次全屏读写" tabindex="-1">④ 后处理：每个 Pass 都是一次全屏读写 <a class="header-anchor" href="#_4-后处理-每个-pass-都是一次全屏读写" aria-label="Permalink to &quot;④ 后处理：每个 Pass 都是一次全屏读写&quot;">​</a></h3><p>1080p 全屏一次读+写约 16.6MB，五段后处理链就是 83MB/帧，60fps 下约 5GB/s。移动端共享带宽常见只有 10~30GB/s，还要和 CPU、显示抢——所以&quot;多一个 Pass&quot;在手机上不是加一点，而是逼近上限。</p><p>优化顺序：能合并的效果合并进同一个 ShaderPass；非必要的 Pass 用半分辨率；能放最后的别拆两段。判断标准：<strong>链上每多一个全屏 Pass，就假设帧时间 +1.5~3ms（移动端）</strong>。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：热力图全红或全蓝，看不出层次？</strong> 色带上限写死了。把 <code>uMax</code> 设成&quot;当前平均 overdraw × 1.5~2&quot;，让映射范围跟着场景走。</li><li><strong>Q：降 DPR 对雾效有用，对别处没用？</strong> 说明瓶颈在片元/带宽；如果降 DPR 完全没反应，瓶颈在 CPU 提交或 JS，回去看 calls 与主线程火焰图。</li><li><strong>Q：关掉雾效还是卡？</strong> 检查是否还有别的半透明层（粒子、光晕、玻璃）以及后处理链长度；overdraw 是累加的，砍一层不够。</li><li><strong>Q：<code>info.memory.textures</code> 一直涨？</strong> 只 <code>scene.remove</code> 不 <code>dispose</code> 就会漏；共享纹理被重复 dispose 也会出问题，谁创建谁负责。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>用一句话定义 overdraw，并写出它的总代价与哪三个量成正比。</li><li>为什么后处理每多一个 Pass，代价是&quot;整张图再来一遍&quot;，而不是&quot;只加一点点&quot;？</li><li>半透明物体为什么通常享受不到 early-z 优化？给出两个替代方案。</li></ol><details><summary>答案</summary><ol><li>overdraw 是同一屏幕像素在一帧里被多个三角形覆盖并着色的次数。总代价 ≈ 像素数 × 每像素指令数 × overdraw 倍数；像素数又等于宽 × 高 × DPR²。</li><li>因为每个 Pass 都要把上一张全屏结果读进来、把新结果写出去：1080p 一次读+写约 16.6MB，五段链就是 83MB/帧，是对像素总量的重复劳动，不是加法。</li><li>透明物体需要与背景混合，必须保留片元颜色，无法像不透明物体那样先做深度测试直接丢弃。替代方案：用 <code>alphaTest</code> 让片元可被裁掉；或改用加法混合并关闭排序与深度写入。</li></ol></details>`,25)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
